**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int R, C;
    plik >> R >> C;
    vector<vector<int>> tab(R, vector<int>(C));
    for (int i = 0; i < R; i++)
        for (int j = 0; j < C; j++)
            plik >> tab[i][j];

    vector<int> minW(R);
    for (int i = 0; i < R; i++) {
        minW[i] = tab[i][0];
        for (int j = 1; j < C; j++)
            if (tab[i][j] < minW[i]) minW[i] = tab[i][j];
    }

    cout << "Minima wierszy:";
    for (int i = 0; i < R; i++) cout << " " << minW[i];
    cout << endl;

    int bestRow = 0;
    for (int i = 1; i < R; i++)
        if (minW[i] > minW[bestRow]) bestRow = i;

    cout << "Maximin: wiersz " << bestRow + 1 << ", wartosc " << minW[bestRow] << endl;
    return 0;
}
```

**Wyjasnienie**: Klasyczny problem maximin (teoria gier). Najpierw wyznaczamy minimum kazdego wiersza, potem szukamy wiersza z najwiekszym minimum.

Weryfikacja:
- Wiersz 1: min(8,15,3,22,10)=3
- Wiersz 2: min(12,7,18,5,14)=5
- Wiersz 3: min(20,9,11,16,6)=6
- Wiersz 4: min(4,25,13,8,19)=4
- Maximin: max(3,5,6,4)=6 w wierszu 3.
